CREATE OR ALTER PROCEDURE [dbo].[uspMaterialConsumptionVariance_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ProductionOrderId UNIQUEIDENTIFIER = NULL
	, @IngredientId UNIQUEIDENTIFIER = NULL
	, @StandardQuantity DECIMAL(18,4) = NULL
	, @ActualQuantity DECIMAL(18,4) = NULL
	, @VarianceQuantity DECIMAL(18,4) = NULL
	, @VarianceCost DECIMAL(18,4) = NULL
	, @Reason NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ProductionOrderId]
			, t.[IngredientId]
			, t.[TheoreticalQty]
			, t.[VariancePercent]
			, t.[VarianceValue]
			, t.[Reason]
			, t.[StandardQuantity]
			, t.[ActualQuantity]
			, t.[VarianceQuantity]
			, t.[VarianceCost]
			, t.[CreatedDate]
		FROM [dbo].[MaterialConsumptionVariance] AS t
		
		WHERE 1 = 1
			AND (@ProductionOrderId IS NULL OR t.[ProductionOrderId] = @ProductionOrderId)
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (@StandardQuantity IS NULL OR t.[StandardQuantity] = @StandardQuantity)
			AND (@ActualQuantity IS NULL OR t.[ActualQuantity] = @ActualQuantity)
			AND (@VarianceQuantity IS NULL OR t.[VarianceQuantity] = @VarianceQuantity)
			AND (@VarianceCost IS NULL OR t.[VarianceCost] = @VarianceCost)
			AND (ISNULL(@Reason, '') = '' OR t.[Reason] LIKE CONCAT('%', @Reason, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionOrderId' THEN r.[ProductionOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionOrderId' THEN r.[ProductionOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'theoreticalQty' THEN r.[TheoreticalQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'theoreticalQty' THEN r.[TheoreticalQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'variancePercent' THEN r.[VariancePercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'variancePercent' THEN r.[VariancePercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'varianceValue' THEN r.[VarianceValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'varianceValue' THEN r.[VarianceValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reason' THEN r.[Reason] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reason' THEN r.[Reason] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardQuantity' THEN r.[StandardQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardQuantity' THEN r.[StandardQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actualQuantity' THEN r.[ActualQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actualQuantity' THEN r.[ActualQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'varianceQuantity' THEN r.[VarianceQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'varianceQuantity' THEN r.[VarianceQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'varianceCost' THEN r.[VarianceCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'varianceCost' THEN r.[VarianceCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
